    "static int dist[8];",
    "static bool visited[8];",
    "static int parent[8];",
    "static int relaxations = 0;",
    "",
    "",
    "// Extracting the minimum by linear scan: O(V) every time, and that's what",
    "// brings the total to O(V^2).",
    "int minDistance() {",
    "    int best = INT_MAX;",
    "    int index = -1;",
    "    for (int v = 0; v < g.size(); v++) {",
    "        if (!visited[v] && dist[v] <= best) {",
    "            best = dist[v];",
    "            index = v;",
    "        }",
    "    }",
