    "",
    "    for (int step = 0; step < g.size(); step++) {",
    "        int u = minDistance();",
    "        if (u < 0 || dist[u] == INT_MAX) break;",
    "",
    "",
    "        visited[u] = true;",
    "",
    "        for (int v = 0; v < g.size(); v++) {",
    "            int w = g.adj[u][v];",
